  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  at timestamptz NOT NULL DEFAULT now(),
  provider text NOT NULL,
  model text NOT NULL,
  label text NOT NULL,
  input integer NOT NULL,
  output integer NOT NULL,
  ms integer NOT NULL,
  status text NOT NULL,
  error text
);
CREATE INDEX llm_usage_at_idx ON llm_usage (at);
CREATE INDEX llm_usage_label_idx ON llm_usage (label);

CREATE TABLE assistant_cache (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspace(id),
  cache_key varchar(64) NOT NULL,
  lease_token uuid,
  text text NOT NULL,
  model text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX assistant_cache_workspace_id_idx ON assistant_cache (workspace_id);
CREATE INDEX assistant_cache_expires_at_idx ON assistant_cache (expires_at);
CREATE UNIQUE INDEX assistant_cache_workspace_id_cache_key_key ON assistant_cache (workspace_id, cache_key);

CREATE TABLE auth_factor (
  subject text PRIMARY KEY,
  secret_sealed text NOT NULL,
  last_step bigint NOT NULL DEFAULT 0,
  backup_codes text[] NOT NULL,
  enabled_at timestamptz,
  failed_count integer NOT NULL DEFAULT 0,
  failed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE auth_step_up (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subject text NOT NULL,
  session_id text NOT NULL,
  purpose text NOT NULL,
  target text NOT NULL DEFAULT '',
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX auth_step_up_session_id_idx ON auth_step_up (session_id);
CREATE UNIQUE INDEX auth_step_up_session_id_purpose_target_key ON auth_step_up (session_id, purpose, target);

CREATE TABLE auth_workspace (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  created_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE auth_invite (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace text NOT NULL,
  email text NOT NULL,
  role text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  invited_by text NOT NULL,
  expires_at timestamptz NOT NULL,
  accepted_at timestamptz,
  accepted_by text,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX auth_invite_workspace_idx ON auth_invite (workspace);

CREATE TABLE smip_peer (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner text NOT NULL,
  domain text NOT NULL,
  origin text NOT NULL DEFAULT '',
  key_id text NOT NULL,
  public_key text NOT NULL,
  not_before timestamptz NOT NULL,
  not_after timestamptz NOT NULL,
  revoked boolean NOT NULL DEFAULT false,
  state text NOT NULL DEFAULT 'pending',
  confirmed boolean NOT NULL DEFAULT false,
  paired_by text NOT NULL DEFAULT '',
  paired_at timestamptz,
  fetched_at timestamptz NOT NULL,
  notes text NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX smip_peer_owner_domain_key_id_key ON smip_peer (owner, domain, key_id);

CREATE TABLE smip_pinned_origin (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  domain text NOT NULL UNIQUE,
  origin text NOT NULL,
  added_by text NOT NULL DEFAULT '',
  added_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE smip_ca_bundle (
  id text PRIMARY KEY,
  pem text NOT NULL,
  updated_by text NOT NULL DEFAULT '',
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE smip_mail_domain (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  origin text NOT NULL,
  domain text NOT NULL,
  state text NOT NULL DEFAULT 'unknown',
  ever_verified boolean NOT NULL DEFAULT false,
  endpoint text NOT NULL DEFAULT '',
  document text NOT NULL DEFAULT '',
  reason text NOT NULL DEFAULT '',
  checked_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL
);
CREATE UNIQUE INDEX smip_mail_domain_origin_domain_key ON smip_mail_domain (origin, domain);

CREATE TABLE mail_transmission (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  origin text NOT NULL,
  workspace_id uuid NOT NULL REFERENCES workspace(id),
  mailbox_id uuid NOT NULL REFERENCES mailbox(id),
  item_id uuid NOT NULL UNIQUE REFERENCES mail_item(id),
  author_id text NOT NULL,
  payload text NOT NULL,
  provider_config text NOT NULL,
  origin_key text NOT NULL,
  state text NOT NULL DEFAULT 'planning',
  api_state text NOT NULL DEFAULT 'pending',
  api_attempt_id text NOT NULL DEFAULT '',
  api_result text NOT NULL DEFAULT '',
  reason text NOT NULL DEFAULT '',
  next_attempt timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE INDEX mail_transmission_workspace_id_idx ON mail_transmission (workspace_id);

CREATE TABLE mail_delivery (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  transmission_id uuid NOT NULL REFERENCES mail_transmission(id),
  recipient text NOT NULL,
  domain text NOT NULL,
  route text NOT NULL DEFAULT 'pending',
  state text NOT NULL DEFAULT 'pending',
  reason text NOT NULL DEFAULT '',
  packet text NOT NULL DEFAULT '',
  peer_document text NOT NULL DEFAULT '',
  receipt text NOT NULL DEFAULT '',
  attempts integer NOT NULL DEFAULT 0,
  attempt_id text NOT NULL DEFAULT '',
  next_attempt timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE INDEX mail_delivery_transmission_id_idx ON mail_delivery (transmission_id);
CREATE UNIQUE INDEX mail_delivery_transmission_id_recipient_key ON mail_delivery (transmission_id, recipient);

CREATE TABLE smip_mail_receipt (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  domain text NOT NULL,
  origin text NOT NULL,
  message_id text NOT NULL,
  recipient text NOT NULL,
  digest text NOT NULL,
  receipt text NOT NULL,
  item_id uuid NOT NULL,
  accepted_at timestamptz NOT NULL
);
CREATE UNIQUE INDEX smip_mail_receipt_domain_origin_message_id_key ON smip_mail_receipt (domain, origin, message_id);

CREATE TABLE mail_protection (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL UNIQUE REFERENCES workspace(id) ON DELETE CASCADE,
  ai_enabled boolean NOT NULL DEFAULT true,
  approve_unknown boolean NOT NULL DEFAULT false,
  sender_per_hour integer NOT NULL DEFAULT 60,
  domain_per_hour integer NOT NULL DEFAULT 600,
  spam_threshold integer NOT NULL DEFAULT 70,
  revision integer NOT NULL DEFAULT 1,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE mail_screening (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  item_id uuid NOT NULL UNIQUE REFERENCES mail_item(id) ON DELETE CASCADE,
  workspace_id uuid NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  sender text NOT NULL,
  domain text NOT NULL,
  identity text NOT NULL,
  authenticated boolean NOT NULL,
  state text NOT NULL DEFAULT 'pending',
  score integer NOT NULL DEFAULT 0,
  findings text NOT NULL DEFAULT '[]',
  ai_state text NOT NULL DEFAULT 'pending',
  av_state text NOT NULL DEFAULT 'pending',
  approval_required boolean NOT NULL DEFAULT false,
  released boolean NOT NULL DEFAULT false,
  attempts integer NOT NULL DEFAULT 0,
  attempt_id text NOT NULL DEFAULT '',
  policy_revision integer NOT NULL,
  next_attempt timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE INDEX mail_screening_workspace_id_idx ON mail_screening (workspace_id);
CREATE INDEX mail_screening_state_next_attempt_idx ON mail_screening (state, next_attempt);
CREATE INDEX mail_screening_workspace_id_domain_authenticated_idx ON mail_screening (workspace_id, domain, authenticated);

CREATE TABLE mail_sender_policy (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  identity text NOT NULL,
  decision text NOT NULL DEFAULT 'neutral',
  updated_by text NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE UNIQUE INDEX mail_sender_policy_workspace_id_identity_key ON mail_sender_policy (workspace_id, identity);

CREATE TABLE mail_complaint (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  item_id uuid NOT NULL REFERENCES mail_item(id) ON DELETE CASCADE,
  identity text NOT NULL,
  subject text NOT NULL,
  active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL
);
CREATE INDEX mail_complaint_workspace_id_idx ON mail_complaint (workspace_id);
CREATE UNIQUE INDEX mail_complaint_item_id_subject_key ON mail_complaint (item_id, subject);
CREATE INDEX mail_complaint_workspace_id_identity_active_idx ON mail_complaint (workspace_id, identity, active);

CREATE TABLE mail_filter_feedback (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  item_id uuid NOT NULL UNIQUE REFERENCES mail_item(id) ON DELETE CASCADE,
  classification text NOT NULL,
  revision integer NOT NULL DEFAULT 1,
  learned_revision integer NOT NULL DEFAULT 0,
  state text NOT NULL DEFAULT 'pending',
  actor text NOT NULL,
  attempts integer NOT NULL DEFAULT 0,
  next_attempt timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE INDEX mail_filter_feedback_workspace_id_idx ON mail_filter_feedback (workspace_id);
CREATE INDEX mail_filter_feedback_state_next_attempt_idx ON mail_filter_feedback (state, next_attempt);

CREATE TABLE mail_intake_rate (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  key text NOT NULL,
  bucket timestamptz NOT NULL,
  count integer NOT NULL DEFAULT 1
);
CREATE INDEX mail_intake_rate_bucket_idx ON mail_intake_rate (bucket);
CREATE UNIQUE INDEX mail_intake_rate_workspace_id_key_bucket_key ON mail_intake_rate (workspace_id, key, bucket);

CREATE TABLE team_domain (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspace(id),
  name varchar(253) NOT NULL,
  challenge varchar(120) NOT NULL,
  verification text NOT NULL DEFAULT 'dns',
  status text NOT NULL DEFAULT 'pending',
  web boolean NOT NULL DEFAULT false,
  mail boolean NOT NULL DEFAULT false,
  verified_at timestamptz,
  checked_at timestamptz,
  valid_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX team_domain_workspace_id_idx ON team_domain (workspace_id);
CREATE UNIQUE INDEX team_domain_workspace_id_name_key ON team_domain (workspace_id, name);

CREATE TABLE team_domain_binding (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name varchar(253) NOT NULL UNIQUE,
  workspace_id uuid NOT NULL REFERENCES workspace(id),
  domain_id uuid NOT NULL UNIQUE REFERENCES team_domain(id)
);
CREATE INDEX team_domain_binding_workspace_id_idx ON team_domain_binding (workspace_id);

CREATE TABLE team_setup (
  workspace_id uuid PRIMARY KEY REFERENCES workspace(id),
  primary_domain text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'draft',
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE team_mail_config (
  domain_id uuid PRIMARY KEY REFERENCES team_domain(id),
  workspace_id uuid NOT NULL REFERENCES workspace(id),
  provider varchar(30) NOT NULL,
  sealed text NOT NULL,
  enabled boolean NOT NULL DEFAULT false,
  smip boolean NOT NULL DEFAULT false,
  postfix boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX team_mail_config_workspace_id_idx ON team_mail_config (workspace_id);

